//! B373 compile-red contract for optional whole-project policy and explicit retirement.
//! M1 allocated accounting double-counts hardlinks/follows symlinks -> allocated_inventory.
//! M2 round close bypass/force exemption -> real_close_refuses_over_budget.
//! M3 keep-window off-by-one/ignore receipts -> round_window.
//! M4 skip preservation digest -> retirement_requires_exact_preservation.
//! M5 ignore lsof/identity -> busy_and_replaced_sites_stay.
//! M6 dry-run writes -> retirement_dry_run_and_real_cli.
#![cfg(feature = "selfhost")]
use orch_host::storage_policy::{assess, preservation_digest, retire_manifest};
use serde_json::json;
use std::{fs,path::{Path,PathBuf},process::Command,os::unix::fs::{MetadataExt,symlink}};
fn git(root:&Path,args:&[&str])->String {let o=Command::new("git").args(["-c","core.fsmonitor=false","-c","core.hooksPath=/dev/null","-c","gc.auto=0","-c","user.name=Fixture","-c","user.email=fixture@example.invalid"]).arg("-C").arg(root).args(args).output().unwrap();assert!(o.status.success(),"{}",String::from_utf8_lossy(&o.stderr));String::from_utf8(o.stdout).unwrap().trim().into()}
fn fixture(label:&str)->PathBuf {let p=orch_host::util::test_scratch_dir(label);git(&p,&["init","-q","-b","main"]);fs::write(p.join(".gitignore"),"coordination/runtime/\n.cowork-temp/\n").unwrap();git(&p,&["add","."]);git(&p,&["commit","-qm","fixture"]);p}
fn policy(root:&Path,limit:u64){fs::create_dir_all(root.join("coordination")).unwrap();fs::write(root.join("coordination/STORAGE-POLICY.yaml"),format!("schemaVersion: 1\nmaxAllocatedBytes: {limit}\nkeepRecentRounds: 3\n")).unwrap();}
fn closed(root:&Path,round:&str){let d=root.join(format!("coordination/rounds/{round}"));fs::create_dir_all(&d).unwrap();let e=orch_host::ledger::event("RoundClosed","runtime:orch",None,Some(round),json!({"forced":false,"unrecorded":[]}));fs::write(d.join("events.jsonl"),format!("{}\n",serde_json::to_string(&e).unwrap())).unwrap();}
fn setup_retirement(root:&Path)->(PathBuf,PathBuf){closed(root,"r90");let source=root.join(".cowork-temp/old-fixture");let backup=root.join("coordination/runtime/site-archives/fixture/source");fs::create_dir_all(&source).unwrap();fs::create_dir_all(&backup).unwrap();fs::write(source.join("unique.txt"),b"unique preserved data").unwrap();fs::copy(source.join("unique.txt"),backup.join("unique.txt")).unwrap();let m=fs::metadata(&source).unwrap();let digest=preservation_digest(&source,&[]).unwrap();assert_eq!(digest,preservation_digest(&backup,&[]).unwrap());let manifest=root.join("retirement.json");fs::write(&manifest,serde_json::to_vec(&json!({"schemaVersion":1,"projectRoot":root,"authorization":"explicit fixture retirement","expiresAt":4102444800u64,"entries":[{"path":".cowork-temp/old-fixture","round":"r90","device":m.dev(),"inode":m.ino(),"head":null,"kind":"directory","sourceDigest":digest,"backupPath":"coordination/runtime/site-archives/fixture/source","excludedCaches":[]}]})).unwrap()).unwrap();(source,manifest)}
#[test]
fn allocated_inventory(){let root=fixture("b372-allocated");assert!(assess(&root,"r96").unwrap().is_none());policy(&root,u64::MAX);fs::write(root.join("data"),vec![1;16384]).unwrap();fs::hard_link(root.join("data"),root.join("same-inode")).unwrap();let outside=orch_host::util::test_scratch_dir("b372-outside");fs::write(outside.join("large"),vec![2;1024*1024]).unwrap();symlink(&outside,root.join("external-link")).unwrap();let v=assess(&root,"r96").unwrap().unwrap();let du=Command::new("du").args(["-sk"]).arg(&root).output().unwrap();assert!(du.status.success());let n:u64=String::from_utf8(du.stdout).unwrap().split_whitespace().next().unwrap().parse().unwrap();assert_eq!(v["projectAllocatedBytes"].as_u64(),Some(n*1024));assert_eq!(v["policySatisfied"],true);policy(&root,1);assert_eq!(assess(&root,"r96").unwrap().unwrap()["policySatisfied"],false);fs::write(root.join("coordination/STORAGE-POLICY.yaml"),"unknown: true\n").unwrap();assert!(assess(&root,"r96").is_err());fs::remove_dir_all(root).unwrap();fs::remove_dir_all(outside).unwrap();}
#[test]
fn real_close_refuses_over_budget(){let root=fixture("b372-close");policy(&root,1);fs::create_dir_all(root.join("coordination/runtime")).unwrap();fs::write(root.join("coordination/runtime/CURRENT-ROUND"),"r96\n").unwrap();for force in [false,true]{let e=orch_host::round::run_close(&root,force,Some("fixture")).err().expect("budget must reject").to_string();assert!(e.contains("storage policy"),"{e}");}assert!(!root.join("coordination/rounds/r96/dispatch/DONE.md").exists());assert!(!root.join("coordination/rounds/r96/events.jsonl").exists());fs::remove_dir_all(root).unwrap();}
#[test]
fn round_window(){let root=fixture("b372-window");policy(&root,u64::MAX);fs::create_dir_all(root.join(".cowork-temp")).unwrap();for (id,round) in [("older","r93"),("retained","r94")]{let path=root.join(format!(".cowork-temp/collect-source-{id}"));fs::create_dir(&path).unwrap();let m=fs::metadata(&path).unwrap();fs::write(root.join(format!(".cowork-temp/collect-source-{id}.receipt.json")),serde_json::to_vec(&json!({"schemaVersion":1,"projectRoot":root,"path":path,"owner":{"round":round,"taskId":"T","attemptId":"T-A1","purpose":"fixture"},"head":"a".repeat(40),"device":m.dev(),"inode":m.ino(),"phase":"retained"})).unwrap()).unwrap();}let v=assess(&root,"r96").unwrap().unwrap();assert_eq!(v["retainedRounds"],json!(["r94","r95","r96"]));assert_eq!(v["expiredPaths"],json!([".cowork-temp/collect-source-older"]));assert_eq!(v["policySatisfied"],false);fs::remove_dir_all(root).unwrap();}
#[test]
fn retirement_requires_exact_preservation(){let root=fixture("b372-preservation");let(source,m)=setup_retirement(&root);fs::write(root.join("coordination/runtime/site-archives/fixture/source/unique.txt"),b"wrong").unwrap();assert!(retire_manifest(&root,&m,false).is_err());assert!(source.exists());fs::remove_dir_all(root).unwrap();}
#[test]
fn busy_and_replaced_sites_stay(){let root=fixture("b372-busy");let(source,m)=setup_retirement(&root);let open=fs::File::open(source.join("unique.txt")).unwrap();assert!(retire_manifest(&root,&m,false).is_err());drop(open);let old=root.join(".cowork-temp/original");fs::rename(&source,&old).unwrap();fs::create_dir(&source).unwrap();fs::write(source.join("unique.txt"),b"unique preserved data").unwrap();assert!(retire_manifest(&root,&m,false).is_err());assert!(old.exists()&&source.exists());fs::remove_dir_all(root).unwrap();}
#[test]
fn retirement_dry_run_and_real_cli(){let root=fixture("b372-retire");let(source,m)=setup_retirement(&root);let before=preservation_digest(&root,&[]).unwrap();let out=Command::new(env!("CARGO_BIN_EXE_orch")).arg("--root").arg(&root).args(["sites","gc","--dry-run","--retire-manifest"]).arg(&m).output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));assert_eq!(before,preservation_digest(&root,&[]).unwrap());assert!(source.exists());let v=retire_manifest(&root,&m,false).unwrap();assert_eq!(v["items"][0]["disposition"],"removed");assert!(!source.exists());let again=retire_manifest(&root,&m,false).unwrap();assert_eq!(again["items"][0]["disposition"],"already-removed");assert_eq!(fs::read(root.join("coordination/runtime/site-archives/fixture/source/unique.txt")).unwrap(),b"unique preserved data");fs::remove_dir_all(root).unwrap();}
